104	    // Client
105	    WebSocketInitResult WebSocketTransport::connectToUrl(const std::string& url,
106	                                                         const WebSocketHttpHeaders& headers,
107	                                                         int timeoutSecs)
108	    {
109	        std::lock_guard<std::mutex> lock(_socketMutex);
110	
111	        std::string protocol, host, path, query;
112	        int port;
113	        std::string remoteUrl(url);
114	
115	        WebSocketInitResult result;
116	        const int maxRedirections = 10;
117	
118	        for (int i = 0; i < maxRedirections; ++i)
119	        {
120	            if (!UrlParser::parse(remoteUrl, protocol, host, path, query, port))
121	            {
122	                std::stringstream ss;
123	                ss << "Could not parse url: '" << url << "'";
124	                return WebSocketInitResult(false, 0, ss.str());
125	            }
126	
127	            std::string errorMsg;
128	            bool tls = protocol == "wss";
129	            _socket = createSocket(tls, -1, errorMsg, _socketTLSOptions);
130	            _perMessageDeflate = ix::make_unique<WebSocketPerMessageDeflate>();
131	
132	            if (!_socket)
133	            {
134	                return WebSocketInitResult(false, 0, errorMsg);
135	            }
136	
137	            WebSocketHandshake webSocketHandshake(_requestInitCancellation,
138	                                                  _socket,
139	                                                  _perMessageDeflate,
140	                                                  _perMessageDeflateOptions,
141	                                                  _enablePerMessageDeflate);
142	
143	            result = webSocketHandshake.clientHandshake(
144	                remoteUrl, headers, protocol, host, path, port, timeoutSecs);
145	
146	            if (result.http_status >= 300 && result.http_status < 400)
147	            {
148	                auto it = result.headers.find("Location");
149	                if (it == result.headers.end())
150	                {
151	                    std::stringstream ss;
152	                    ss << "Missing Location Header for HTTP Redirect response. "
153	                       << "Rejecting connection to " << url << ", status: " << result.http_status;
154	                    result.errorStr = ss.str();
155	                    break;
156	                }
157	
158	                remoteUrl = it->second;
159	                continue;
160	            }
161	
162	            if (result.success)
163	            {
164	                setReadyState(ReadyState::OPEN);
165	            }
166	            return result;
167	        }
168	
169	        return result;
170	    }
