172	    // Server
173	    WebSocketInitResult WebSocketTransport::connectToSocket(std::unique_ptr<Socket> socket,
174	                                                            int timeoutSecs,
175	                                                            bool enablePerMessageDeflate,
176	                                                            HttpRequestPtr request,
177	                                                            int sendTimeoutSecs)
178	    {
179	        std::lock_guard<std::mutex> lock(_socketMutex);
180	
181	        // Server should not mask the data it sends to the client
182	        _useMask = false;
183	        _blockingSend = true;
184	        _sendTimeoutSecs = sendTimeoutSecs;
185	
186	        _socket = std::move(socket);
187	        _perMessageDeflate = ix::make_unique<WebSocketPerMessageDeflate>();
188	
189	        WebSocketHandshake webSocketHandshake(_requestInitCancellation,
190	                                              _socket,
191	                                              _perMessageDeflate,
192	                                              _perMessageDeflateOptions,
193	                                              _enablePerMessageDeflate);
194	
195	        auto result =
196	            webSocketHandshake.serverHandshake(timeoutSecs, enablePerMessageDeflate, request);
197	        if (result.success)
198	        {
199	            setReadyState(ReadyState::OPEN);
200	        }
201	        return result;
202	    }
