253	    // Only consider send PING time points for that computation.
254	    bool WebSocketTransport::pingIntervalExceeded()
255	    {
256	        if (_pingIntervalSecs <= 0) return false;
257	
258	        std::lock_guard<std::mutex> lock(_lastSendPingTimePointMutex);
259	        auto now = std::chrono::steady_clock::now();
260	        return now - _lastSendPingTimePoint > std::chrono::seconds(_pingIntervalSecs);
261	    }
