270	    WebSocketSendInfo WebSocketTransport::sendHeartBeat(SendMessageKind pingMessage)
271	    {
272	        _pongReceived = false;
273	        std::stringstream ss;
274	
275	        ss << _kPingMessage;
276	        if (!_setCustomMessage)
277	        {
278	            ss << "::" << _pingIntervalSecs << "s"
279	               << "::" << _pingCount++;
280	        }
281	        if (pingMessage == SendMessageKind::Ping)
282	        {
283	            return sendPing(ss.str());
284	        }
285	        else if (pingMessage == SendMessageKind::Binary)
286	        {
287	            WebSocketSendInfo info = sendBinary(ss.str(), nullptr);
288	            if (info.success)
289	            {
290	                std::lock_guard<std::mutex> lck(_lastSendPingTimePointMutex);
291	                _lastSendPingTimePoint = std::chrono::steady_clock::now();
292	            }
293	            return info;
294	        }
295	        else if (pingMessage == SendMessageKind::Text)
296	        {
297	            WebSocketSendInfo info = sendText(ss.str(), nullptr);
298	            if (info.success)
299	            {
300	                std::lock_guard<std::mutex> lck(_lastSendPingTimePointMutex);
301	                _lastSendPingTimePoint = std::chrono::steady_clock::now();
302	            }
303	            return info;
304	        }
305	
306	        // unknow type ping message
307	        return {};
308	    }
