791	    void WebSocketTransport::emitMessage(MessageKind messageKind,
792	                                         const std::string& message,
793	                                         bool compressedMessage,
794	                                         const OnMessageCallback& onMessageCallback)
795	    {
796	        size_t wireSize = message.size();
797	
798	        // When the RSV1 bit is 1 it means the message is compressed
799	        if (compressedMessage && messageKind != MessageKind::FRAGMENT)
800	        {
801	            bool success = _perMessageDeflate->decompress(message, _decompressedMessage);
802	
803	            if (messageKind == MessageKind::MSG_TEXT && !validateUtf8(_decompressedMessage))
804	            {
805	                close(WebSocketCloseConstants::kInvalidFramePayloadData,
806	                      WebSocketCloseConstants::kInvalidFramePayloadDataMessage);
807	            }
808	            else
809	            {
810	                onMessageCallback(_decompressedMessage, wireSize, !success, messageKind);
811	            }
812	        }
813	        else
814	        {
815	            if (messageKind == MessageKind::MSG_TEXT && !validateUtf8(message))
816	            {
817	                close(WebSocketCloseConstants::kInvalidFramePayloadData,
818	                      WebSocketCloseConstants::kInvalidFramePayloadDataMessage);
819	            }
820	            else
821	            {
822	                onMessageCallback(message, wireSize, false, messageKind);
823	            }
824	        }
825	    }
