194	            // otherwise automatic reconnection might restart the connection before _stop has a chance to get set
195	            // this can happen during high CPU load => _thread.join() below blocks indefinitely
196	            _stop = true;
197	            _sleepCondition.notify_one();
198	        }
199	
200	        close(code, reason);
201	
202	        if (isJoinable)
