211	    WebSocketInitResult WebSocket::connect(int timeoutSecs)
212	    {
213	        {
214	            std::lock_guard<std::mutex> lock(_configMutex);
215	            _ws.configure(
216	                _perMessageDeflateOptions, _socketTLSOptions, _enablePong, _pingIntervalSecs);
217	        }
218	
219	        WebSocketHttpHeaders headers(_extraHeaders);
220	        std::string subProtocolsHeader;
221	        const auto &subProtocols = getSubProtocols();
222	        if (!subProtocols.empty())
223	        {
224	            //
225	            // Sub Protocol strings are comma separated.
226	            // Python code to do that is:
227	            // >>> ','.join(['json', 'msgpack'])
228	            // 'json,msgpack'
229	            //
230	            int i = 0;
231	            for (const auto & subProtocol : subProtocols)
232	            {
233	                if (i++ != 0)
234	                {
235	                    subProtocolsHeader += ",";
236	                }
237	                subProtocolsHeader += subProtocol;
238	            }
239	            headers["Sec-WebSocket-Protocol"] = subProtocolsHeader;
240	        }
241	
242	        WebSocketInitResult status = _ws.connectToUrl(_url, headers, timeoutSecs);
243	        if (!status.success)
244	        {
245	            return status;
246	        }
247	
248	        _onMessageCallback(ix::make_unique<WebSocketMessage>(
249	            WebSocketMessageType::Open,
250	            emptyMsg,
251	            0,
252	            WebSocketErrorInfo(),
253	            WebSocketOpenInfo(status.uri, status.headers, status.protocol),
254	            WebSocketCloseInfo()));
255	
256	        if (_pingIntervalSecs > 0)
257	        {
258	            // Send a heart beat right away
259	            _ws.sendHeartBeat(_pingType);
260	        }
261	
262	        return status;
263	    }
