316	    void WebSocket::checkConnection(bool firstConnectionAttempt)
317	    {
318	        using millis = std::chrono::duration<double, std::milli>;
319	
320	        uint32_t retries = 0;
321	        millis duration(0);
322	
323	        // Try to connect perpetually
324	        while (true)
325	        {
326	            if (isConnected() || isClosing() || _stop)
327	            {
328	                break;
329	            }
330	
331	            if (!firstConnectionAttempt && !_automaticReconnection)
332	            {
333	                // Do not attempt to reconnect
334	                break;
335	            }
336	
337	            firstConnectionAttempt = false;
338	
339	            // Only sleep if we are retrying
340	            if (duration.count() > 0)
341	            {
342	                std::unique_lock<std::mutex> lock(_sleepMutex);
343	                _sleepCondition.wait_for(lock, duration);
344	            }
345	
346	            if (_stop)
347	            {
348	                break;
349	            }
350	
351	            // Try to connect synchronously
352	            ix::WebSocketInitResult status = connect(_handshakeTimeoutSecs);
353	
354	            if (!status.success)
355	            {
356	                WebSocketErrorInfo connectErr;
357	
358	                if (_automaticReconnection)
359	                {
360	                    duration =
361	                        millis(calculateRetryWaitMilliseconds(retries++,
362	                                                              _maxWaitBetweenReconnectionRetries,
363	                                                              _minWaitBetweenReconnectionRetries));
364	
365	                    connectErr.wait_time = duration.count();
366	                    connectErr.retries = retries;
367	                }
368	
369	                connectErr.reason = status.errorStr;
370	                connectErr.http_status = status.http_status;
371	
372	                _onMessageCallback(ix::make_unique<WebSocketMessage>(WebSocketMessageType::Error,
373	                                                                     emptyMsg,
374	                                                                     0,
375	                                                                     connectErr,
376	                                                                     WebSocketOpenInfo(),
377	                                                                     WebSocketCloseInfo()));
378	            }
379	        }
380	    }
381	
382	    void WebSocket::run()
383	    {
384	        if (_autoThreadName)
385	        {
386	            setThreadName(getUrl());
387	        }
388	
389	        bool firstConnectionAttempt = true;
390	
391	        while (true)
392	        {
393	            // 1. Make sure we are always connected
394	            checkConnection(firstConnectionAttempt);
395	
396	            firstConnectionAttempt = false;
397	
398	            // if here we are closed then checkConnection was not able to connect
399	            if (getReadyState() == ReadyState::Closed)
400	            {
401	                break;
402	            }
403	
404	            // We can avoid to poll if we want to stop and are not closing
405	            if (_stop && !isClosing()) break;
406	
407	            // 2. Poll to see if there's any new data available
408	            WebSocketTransport::PollResult pollResult = _ws.poll();
409	
410	            // 3. Dispatch the incoming messages
411	            _ws.dispatch(
412	                pollResult,
413	                [this](const std::string& msg,
414	                       size_t wireSize,
415	                       bool decompressionError,
416	                       WebSocketTransport::MessageKind messageKind)
417	                {
418	                    WebSocketMessageType webSocketMessageType {WebSocketMessageType::Error};
419	                    switch (messageKind)
420	                    {
421	                        case WebSocketTransport::MessageKind::MSG_TEXT:
422	                        case WebSocketTransport::MessageKind::MSG_BINARY:
423	                        {
424	                            webSocketMessageType = WebSocketMessageType::Message;
425	                        }
426	                        break;
427	
428	                        case WebSocketTransport::MessageKind::PING:
429	                        {
430	                            webSocketMessageType = WebSocketMessageType::Ping;
431	                        }
432	                        break;
433	
434	                        case WebSocketTransport::MessageKind::PONG:
435	                        {
436	                            webSocketMessageType = WebSocketMessageType::Pong;
437	                        }
438	                        break;
439	
440	                        case WebSocketTransport::MessageKind::FRAGMENT:
441	                        {
442	                            webSocketMessageType = WebSocketMessageType::Fragment;
443	                        }
444	                        break;
445	                    }
446	
447	                    WebSocketErrorInfo webSocketErrorInfo;
448	                    webSocketErrorInfo.decompressionError = decompressionError;
449	
450	                    bool binary = messageKind == WebSocketTransport::MessageKind::MSG_BINARY;
451	
452	                    _onMessageCallback(ix::make_unique<WebSocketMessage>(webSocketMessageType,
453	                                                                         msg,
454	                                                                         wireSize,
455	                                                                         webSocketErrorInfo,
456	                                                                         WebSocketOpenInfo(),
457	                                                                         WebSocketCloseInfo(),
458	                                                                         binary));
459	
460	                    WebSocket::invokeTrafficTrackerCallback(wireSize, true);
461	                });
462	        }
463	    }
