595	            case ix::WebSocketTransport::ReadyState::CLOSING: return ReadyState::Closing;
596	            case ix::WebSocketTransport::ReadyState::CLOSED: return ReadyState::Closed;
597	            default: return ReadyState::Closed;
598	        }
