static void setupClient(ix::WebSocket& ws, Recorder& rec, uint16_t port)
{
    ws.setUrl("ws://127.0.0.1:" + std::to_string(port) + "/");
    ws.setOnMessageCallback([&rec](const ix::WebSocketMessagePtr& msg) {
        Event e;
        switch (msg->type)
        {
            case ix::WebSocketMessageType::Message: e.type = "Message"; e.payload = msg->str; e.binary = msg->binary; break;
            case ix::WebSocketMessageType::Fragment: e.type = "Fragment"; break;
            case ix::WebSocketMessageType::Ping: e.type = "Ping"; e.payload = msg->str; break;
            case ix::WebSocketMessageType::Pong: e.type = "Pong"; e.payload = msg->str; break;
            case ix::WebSocketMessageType::Open: e.type = "Open"; break;
            case ix::WebSocketMessageType::Close:
                e.type = "Close"; e.code = msg->closeInfo.code; e.reason = msg->closeInfo.reason; break;
            case ix::WebSocketMessageType::Error: e.type = "Error"; e.payload = msg->errorInfo.reason; break;
        }
        rec.add(e);
    });
}
