// Verification test for fragmented message reception in IXWebSocketTransport.
// Uses a raw-socket fake WebSocket server to send hand-crafted frames to an
// ix::WebSocket client and observe the callbacks / close behavior.

#include <ixwebsocket/IXWebSocket.h>
#include <ixwebsocket/IXWebSocketHandshakeKeyGen.h>

#include <arpa/inet.h>
#include <netinet/in.h>
#include <poll.h>
#include <sys/socket.h>
#include <unistd.h>
#include <zlib.h>

#include <chrono>
#include <condition_variable>
#include <cstring>
#include <iostream>
#include <mutex>
#include <string>
#include <thread>
#include <vector>

static int g_failures = 0;

#define CHECK(cond, msg)                                                                         \
    do                                                                                           \
    {                                                                                            \
        if (!(cond))                                                                             \
        {                                                                                        \
            std::cerr << "FAIL: " << msg << " (" << #cond << ") line " << __LINE__ << std::endl; \
            ++g_failures;                                                                        \
        }                                                                                        \
    } while (0)

struct Event
{
    std::string type;
    std::string payload;
    bool binary = false;
    uint16_t code = 0;
    std::string reason;
};

struct Recorder
{
    std::mutex mutex;
    std::condition_variable cv;
    std::vector<Event> events;

    void add(const Event& e)
    {
        {
            std::lock_guard<std::mutex> lock(mutex);
            events.push_back(e);
        }
        cv.notify_all();
    }

    template<typename Pred>
    bool waitFor(Pred pred, int timeoutMs)
    {
        std::unique_lock<std::mutex> lock(mutex);
        return cv.wait_for(lock, std::chrono::milliseconds(timeoutMs), [&] { return pred(events); });
    }

    size_t count(const std::string& type)
    {
        std::lock_guard<std::mutex> lock(mutex);
        size_t n = 0;
        for (auto& e : events)
            if (e.type == type) n++;
        return n;
    }

    std::vector<std::string> messages()
    {
        std::lock_guard<std::mutex> lock(mutex);
        std::vector<std::string> out;
        for (auto& e : events)
            if (e.type == "Message") out.push_back(e.payload);
        return out;
    }

    bool lastClose(uint16_t& code, std::string& reason)
    {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto it = events.rbegin(); it != events.rend(); ++it)
        {
            if (it->type == "Close")
            {
                code = it->code;
                reason = it->reason;
                return true;
            }
        }
        return false;
    }
};

struct Conn
{
    int fd = -1;

    bool sendRaw(const std::string& data)
    {
        size_t off = 0;
        while (off < data.size())
        {
            ssize_t n = ::send(fd, data.data() + off, data.size() - off, 0);
            if (n <= 0) return false;
            off += (size_t) n;
        }
        return true;
    }

    bool sendFrame(bool fin, bool rsv1, uint8_t opcode, const std::string& payload)
    {
        std::string frame;
        uint8_t b0 = (uint8_t)((fin ? 0x80 : 0) | (rsv1 ? 0x40 : 0) | (opcode & 0x0f));
        frame.push_back((char) b0);
        size_t len = payload.size();
        if (len < 126)
        {
            frame.push_back((char) len);
        }
        else if (len <= 0xffff)
        {
            frame.push_back((char) 126);
            frame.push_back((char)((len >> 8) & 0xff));
            frame.push_back((char)(len & 0xff));
        }
        else
        {
            frame.push_back((char) 127);
            for (int i = 7; i >= 0; --i) frame.push_back((char)((len >> (8 * i)) & 0xff));
        }
        frame += payload;
        return sendRaw(frame);
    }

    bool readN(char* buf, size_t n, int timeoutMs)
    {
        size_t off = 0;
        while (off < n)
        {
            struct pollfd pfd
            {
                fd, POLLIN, 0
            };
            int r = poll(&pfd, 1, timeoutMs);
            if (r <= 0) return false;
            ssize_t got = recv(fd, buf + off, n - off, 0);
            if (got <= 0) return false;
            off += (size_t) got;
        }
        return true;
    }

    bool readFrame(bool& fin, uint8_t& opcode, std::string& payload, int timeoutMs = 5000)
    {
        char hdr[2];
        if (!readN(hdr, 2, timeoutMs)) return false;
        fin = (hdr[0] & 0x80) != 0;
        opcode = (uint8_t)(hdr[0] & 0x0f);
        bool mask = (hdr[1] & 0x80) != 0;
        uint64_t len = (uint8_t) hdr[1] & 0x7f;
        if (len == 126)
        {
            char e[2];
            if (!readN(e, 2, timeoutMs)) return false;
            len = ((uint64_t)(uint8_t) e[0] << 8) | (uint8_t) e[1];
        }
        else if (len == 127)
        {
            char e[8];
            if (!readN(e, 8, timeoutMs)) return false;
            len = 0;
            for (int i = 0; i < 8; ++i) len = (len << 8) | (uint8_t) e[i];
        }
        uint8_t maskingKey[4] = {0, 0, 0, 0};
        if (mask)
        {
            char mk[4];
            if (!readN(mk, 4, timeoutMs)) return false;
            for (int i = 0; i < 4; ++i) maskingKey[i] = (uint8_t) mk[i];
        }
        payload.assign((size_t) len, '\0');
        if (len > 0 && !readN(&payload[0], (size_t) len, timeoutMs)) return false;
        if (mask)
            for (uint64_t i = 0; i < len; ++i) payload[(size_t) i] ^= (char) maskingKey[i & 3];
        return true;
    }

    void closeFd()
    {
        if (fd >= 0)
        {
            ::close(fd);
            fd = -1;
        }
    }
};

struct TestServer
{
    int listenFd = -1;
    uint16_t port = 0;

    bool start()
    {
        listenFd = socket(AF_INET, SOCK_STREAM, 0);
        int opt = 1;
        setsockopt(listenFd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
        sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        addr.sin_port = 0;
        if (bind(listenFd, (sockaddr*) &addr, sizeof(addr)) < 0) return false;
        if (listen(listenFd, 4) < 0) return false;
        socklen_t len = sizeof(addr);
        getsockname(listenFd, (sockaddr*) &addr, &len);
        port = ntohs(addr.sin_port);
        return true;
    }

    bool acceptAndHandshake(Conn& conn, bool enableDeflate = false)
    {
        int fd = accept(listenFd, nullptr, nullptr);
        if (fd < 0) return false;
        conn.fd = fd;
        std::string req;
        char buf[1024];
        while (req.find("\r\n\r\n") == std::string::npos)
        {
            ssize_t n = recv(fd, buf, sizeof(buf), 0);
            if (n <= 0) return false;
            req.append(buf, (size_t) n);
        }
        std::string marker = "Sec-WebSocket-Key: ";
        auto pos = req.find(marker);
        if (pos == std::string::npos) return false;
        pos += marker.size();
        auto eol = req.find("\r\n", pos);
        std::string key = req.substr(pos, eol - pos);
        while (!key.empty() && key.back() == ' ') key.pop_back();
        while (!key.empty() && key.front() == ' ') key.erase(key.begin());

        char acceptKey[29] = {};
        WebSocketHandshakeKeyGen::generate(key, acceptKey);

        std::string resp = "HTTP/1.1 101 Switching Protocols\r\n"
                           "Upgrade: websocket\r\n"
                           "Connection: Upgrade\r\n"
                           "Sec-WebSocket-Accept: " +
                           std::string(acceptKey) + "\r\n";
        if (enableDeflate) resp += "Sec-WebSocket-Extensions: permessage-deflate\r\n";
        resp += "\r\n";
        return conn.sendRaw(resp);
    }

    ~TestServer()
    {
        if (listenFd >= 0) ::close(listenFd);
    }
};

static void setupClient(ix::WebSocket& ws, Recorder& rec, uint16_t port)
{
    ws.setUrl("ws://127.0.0.1:" + std::to_string(port) + "/");
    ws.setOnMessageCallback([&rec](const ix::WebSocketMessagePtr& msg) {
        Event e;
        switch (msg->type)
        {
            case ix::WebSocketMessageType::Message:
                e.type = "Message";
                e.payload = msg->str;
                e.binary = msg->binary;
                break;
            case ix::WebSocketMessageType::Fragment: e.type = "Fragment"; break;
            case ix::WebSocketMessageType::Ping:
                e.type = "Ping";
                e.payload = msg->str;
                break;
            case ix::WebSocketMessageType::Pong:
                e.type = "Pong";
                e.payload = msg->str;
                break;
            case ix::WebSocketMessageType::Open: e.type = "Open"; break;
            case ix::WebSocketMessageType::Close:
                e.type = "Close";
                e.code = msg->closeInfo.code;
                e.reason = msg->closeInfo.reason;
                break;
            case ix::WebSocketMessageType::Error:
                e.type = "Error";
                e.payload = msg->errorInfo.reason;
                break;
        }
        rec.add(e);
    });
}

static bool waitClose(Recorder& rec, int timeoutMs = 5000)
{
    return rec.waitFor([](const std::vector<Event>& ev) {
        for (auto& e : ev)
            if (e.type == "Close") return true;
        return false;
    },
                       timeoutMs);
}

static bool waitOpenCount(Recorder& rec, size_t n, int timeoutMs = 5000)
{
    return rec.waitFor([n](const std::vector<Event>& ev) {
        size_t c = 0;
        for (auto& e : ev)
            if (e.type == "Open") c++;
        return c >= n;
    },
                       timeoutMs);
}

static bool waitMessageCount(Recorder& rec, size_t n, int timeoutMs = 5000)
{
    return rec.waitFor([n](const std::vector<Event>& ev) {
        size_t c = 0;
        for (auto& e : ev)
            if (e.type == "Message") c++;
        return c >= n;
    },
                       timeoutMs);
}

static bool waitFragmentCount(Recorder& rec, size_t n, int timeoutMs = 5000)
{
    return rec.waitFor([n](const std::vector<Event>& ev) {
        size_t c = 0;
        for (auto& e : ev)
            if (e.type == "Fragment") c++;
        return c >= n;
    },
                       timeoutMs);
}

// Read a close frame sent by the client; returns code and reason.
static bool readClientClose(Conn& conn, uint16_t& code, std::string& reason)
{
    bool fin;
    uint8_t opcode;
    std::string payload;
    if (!conn.readFrame(fin, opcode, payload)) return false;
    if (opcode != 0x8) return false;
    if (payload.size() >= 2)
    {
        code = (uint16_t)(((uint8_t) payload[0] << 8) | (uint8_t) payload[1]);
        reason = payload.substr(2);
    }
    else
    {
        code = 1005;
        reason = "";
    }
    return true;
}

static std::string deflateRaw(const std::string& in)
{
    z_stream zs{};
    deflateInit2(&zs, Z_DEFAULT_COMPRESSION, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY);
    zs.next_in = (Bytef*) in.data();
    zs.avail_in = (uInt) in.size();
    std::string out;
    char buf[256];
    int ret;
    do
    {
        zs.next_out = (Bytef*) buf;
        zs.avail_out = sizeof(buf);
        ret = deflate(&zs, Z_SYNC_FLUSH);
        out.append(buf, sizeof(buf) - zs.avail_out);
    } while (ret == Z_OK && zs.avail_out == 0);
    deflateEnd(&zs);
    if (out.size() >= 4) out.resize(out.size() - 4); // strip 00 00 ff ff
    return out;
}

// S1: valid fragmented text message with an interleaved ping
static void s1_fragmented_with_ping()
{
    std::cerr << "S1: fragmented message with interleaved ping" << std::endl;
    TestServer server;
    CHECK(server.start(), "server start");
    ix::WebSocket ws;
    Recorder rec;
    setupClient(ws, rec, server.port);
    ws.start();

    Conn conn;
    CHECK(server.acceptAndHandshake(conn), "handshake");
    CHECK(waitOpenCount(rec, 1), "open");

    conn.sendFrame(false, false, 0x1, "Hello, ");
    conn.sendFrame(true, false, 0x9, "hb"); // ping
    conn.sendFrame(false, false, 0x0, "wor");
    conn.sendFrame(true, false, 0x0, "ld");

    CHECK(waitMessageCount(rec, 1), "one message delivered");
    auto msgs = rec.messages();
    CHECK(msgs.size() == 1 && msgs[0] == "Hello, world", "message content assembled in order");
    CHECK(rec.count("Fragment") == 2, "two fragment notifications");
    CHECK(rec.count("Ping") == 1, "ping notified");

    // client should have auto-replied with a pong carrying "hb"
    bool fin;
    uint8_t opcode;
    std::string payload;
    CHECK(conn.readFrame(fin, opcode, payload), "read client pong");
    CHECK(opcode == 0xA && payload == "hb", "auto pong reply with ping payload");

    // clean close from server
    conn.sendFrame(true, false, 0x8, std::string("\x03\xe8", 2));
    CHECK(waitClose(rec), "close event");
    conn.closeFd();
    ws.stop();
}

// S2: continuation frame without a pending message -> 1002 continuation out of sequence
static void s2_unexpected_continuation()
{
    std::cerr << "S2: continuation without pending message" << std::endl;
    TestServer server;
    CHECK(server.start(), "server start");
    ix::WebSocket ws;
    Recorder rec;
    setupClient(ws, rec, server.port);
    ws.start();

    Conn conn;
    CHECK(server.acceptAndHandshake(conn), "handshake");
    CHECK(waitOpenCount(rec, 1), "open");

    conn.sendFrame(true, false, 0x0, "abc"); // continuation, nothing pending

    uint16_t code;
    std::string reason;
    CHECK(readClientClose(conn, code, reason), "client close frame");
    CHECK(code == 1002, "close code 1002");
    CHECK(reason.find("continuation") != std::string::npos, "reason mentions continuation");

    CHECK(waitClose(rec), "close event");
    uint16_t cbCode;
    std::string cbReason;
    CHECK(rec.lastClose(cbCode, cbReason), "close callback");
    CHECK(cbCode == 1002, "callback code 1002");
    CHECK(cbReason.find("continuation") != std::string::npos,
          "callback reason mentions continuation");
    CHECK(rec.count("Message") == 0 && rec.count("Fragment") == 0,
          "no message/fragment delivered");
    CHECK(rec.count("Close") == 1, "exactly one close notification");
    conn.closeFd();
    ws.stop();
}

// S3: new data frame while a fragmented message is pending -> 1002 data out of sequence,
// and trailing frames received in the same batch must not be delivered either.
static void s3_data_frame_while_pending()
{
    std::cerr << "S3: new data frame while fragmented message pending" << std::endl;
    TestServer server;
    CHECK(server.start(), "server start");
    ix::WebSocket ws;
    Recorder rec;
    setupClient(ws, rec, server.port);
    ws.start();

    Conn conn;
    CHECK(server.acceptAndHandshake(conn), "handshake");
    CHECK(waitOpenCount(rec, 1), "open");

    conn.sendFrame(false, false, 0x1, "AB"); // start fragmented message
    CHECK(waitFragmentCount(rec, 1), "fragment notified");

    // offending frame + another frame, all in one write
    std::string batch;
    batch += std::string("\x81\x02", 2); // TEXT fin, len 2
    batch += "CD";
    batch += std::string("\x81\x02", 2); // TEXT fin, len 2
    batch += "EF";
    conn.sendRaw(batch);

    uint16_t code;
    std::string reason;
    CHECK(readClientClose(conn, code, reason), "client close frame");
    CHECK(code == 1002, "close code 1002");
    CHECK(reason.find("data message") != std::string::npos, "reason mentions data message");

    CHECK(waitClose(rec), "close event");
    CHECK(rec.count("Message") == 0, "no message delivered after violation");
    CHECK(rec.count("Fragment") == 1, "only the pre-violation fragment notified");
    CHECK(rec.count("Close") == 1, "exactly one close notification");
    conn.closeFd();
    ws.stop();
}

// S4: automatic reconnection must not carry over a pending fragmented message
static void s4_reconnect_resets_state()
{
    std::cerr << "S4: reconnect starts with clean fragmentation state" << std::endl;
    TestServer server;
    CHECK(server.start(), "server start");
    ix::WebSocket ws;
    Recorder rec;
    setupClient(ws, rec, server.port);
    ws.start();

    Conn c1;
    CHECK(server.acceptAndHandshake(c1), "handshake 1");
    CHECK(waitOpenCount(rec, 1), "open 1");

    c1.sendFrame(false, false, 0x1, "LEFTOVER"); // never finished
    CHECK(waitFragmentCount(rec, 1), "fragment notified");
    c1.closeFd();                               // abrupt drop

    // client reconnects automatically
    Conn c2;
    CHECK(server.acceptAndHandshake(c2), "handshake 2");
    CHECK(waitOpenCount(rec, 2), "open 2");

    // first frame on the new connection is a continuation: protocol error,
    // and it must NOT be appended to the old pending message
    c2.sendFrame(true, false, 0x0, "x");
    uint16_t code;
    std::string reason;
    CHECK(readClientClose(c2, code, reason), "client close frame");
    CHECK(code == 1002, "close code 1002");
    CHECK(reason.find("continuation") != std::string::npos, "reason mentions continuation");
    CHECK(waitClose(rec, 5000), "close event for connection 2");
    CHECK(rec.count("Message") == 0, "no stale message delivered");
    c2.closeFd();

    // reconnect again: normal single-frame and fragmented messages must work
    Conn c3;
    CHECK(server.acceptAndHandshake(c3), "handshake 3");
    CHECK(waitOpenCount(rec, 3), "open 3");

    c3.sendFrame(true, false, 0x1, "fresh");
    CHECK(waitMessageCount(rec, 1), "single frame message on new connection");

    c3.sendFrame(false, false, 0x1, "A");
    c3.sendFrame(true, false, 0x0, "B");
    CHECK(waitMessageCount(rec, 2), "fragmented message on new connection");

    auto msgs = rec.messages();
    CHECK(msgs.size() == 2 && msgs[0] == "fresh" && msgs[1] == "AB",
          "new connection messages have no leftover content");

    c3.sendFrame(true, false, 0x8, std::string("\x03\xe8", 2));
    waitClose(rec);
    c3.closeFd();
    ws.stop();
}

// S5: empty non-final frame still opens a message
static void s5_empty_non_final_frame()
{
    std::cerr << "S5: empty non-final frame keeps message open" << std::endl;
    TestServer server;
    CHECK(server.start(), "server start");
    ix::WebSocket ws;
    Recorder rec;
    setupClient(ws, rec, server.port);
    ws.start();

    Conn conn;
    CHECK(server.acceptAndHandshake(conn), "handshake");
    CHECK(waitOpenCount(rec, 1), "open");

    // empty non-final text frame, then final continuation
    conn.sendFrame(false, false, 0x1, "");
    conn.sendFrame(true, false, 0x0, "X");
    CHECK(waitMessageCount(rec, 1), "message delivered");
    auto msgs = rec.messages();
    CHECK(msgs.size() == 1 && msgs[0] == "X", "content from continuation only");

    // empty non-final text frame, then a NEW text frame -> protocol error
    conn.sendFrame(false, false, 0x1, "");
    conn.sendFrame(true, false, 0x1, "Y");
    uint16_t code;
    std::string reason;
    CHECK(readClientClose(conn, code, reason), "client close frame");
    CHECK(code == 1002, "close code 1002");
    CHECK(reason.find("data message") != std::string::npos, "reason mentions data message");
    CHECK(waitClose(rec), "close event");
    CHECK(rec.count("Message") == 1, "no extra message delivered");
    conn.closeFd();
    ws.stop();
}

// S6: multi-byte UTF-8 character split across fragments
static void s6_utf8_split()
{
    std::cerr << "S6: utf-8 character split across fragments" << std::endl;
    TestServer server;
    CHECK(server.start(), "server start");
    ix::WebSocket ws;
    Recorder rec;
    setupClient(ws, rec, server.port);
    ws.start();

    Conn conn;
    CHECK(server.acceptAndHandshake(conn), "handshake");
    CHECK(waitOpenCount(rec, 1), "open");

    // U+00E9 (e-acute) = 0xC3 0xA9, split in the middle
    conn.sendFrame(false, false, 0x1, std::string("\xc3", 1));
    conn.sendFrame(true, false, 0x0, std::string("\xa9", 1));
    CHECK(waitMessageCount(rec, 1), "message delivered");
    auto msgs = rec.messages();
    CHECK(msgs.size() == 1 && msgs[0] == "\xc3\xa9", "utf-8 char reassembled");

    conn.sendFrame(true, false, 0x8, std::string("\x03\xe8", 2));
    waitClose(rec);
    conn.closeFd();
    ws.stop();
}

// S7: zero bytes preserved in binary fragments
static void s7_binary_zero_bytes()
{
    std::cerr << "S7: zero bytes preserved in binary message" << std::endl;
    TestServer server;
    CHECK(server.start(), "server start");
    ix::WebSocket ws;
    Recorder rec;
    setupClient(ws, rec, server.port);
    ws.start();

    Conn conn;
    CHECK(server.acceptAndHandshake(conn), "handshake");
    CHECK(waitOpenCount(rec, 1), "open");

    conn.sendFrame(false, false, 0x2, std::string("\x00\x01", 2));
    conn.sendFrame(true, false, 0x0, std::string("\x00\x02", 2));
    CHECK(waitMessageCount(rec, 1), "message delivered");
    auto msgs = rec.messages();
    std::string expected("\x00\x01\x00\x02", 4);
    CHECK(msgs.size() == 1 && msgs[0] == expected, "zero bytes preserved");
    CHECK(rec.waitFor([](const std::vector<Event>& ev) {
        for (auto& e : ev)
            if (e.type == "Message") return e.binary;
        return false;
    },
                      1000),
          "message flagged binary");

    conn.sendFrame(true, false, 0x8, std::string("\x03\xe8", 2));
    waitClose(rec);
    conn.closeFd();
    ws.stop();
}

// S8: stop() then start() again on the same object resets state
static void s8_stop_start_resets_state()
{
    std::cerr << "S8: stop/start resets fragmentation state" << std::endl;
    TestServer server;
    CHECK(server.start(), "server start");
    ix::WebSocket ws;
    Recorder rec;
    setupClient(ws, rec, server.port);
    ws.start();

    Conn c1;
    CHECK(server.acceptAndHandshake(c1), "handshake 1");
    CHECK(waitOpenCount(rec, 1), "open 1");

    c1.sendFrame(false, false, 0x1, "PENDING"); // never finished
    CHECK(waitFragmentCount(rec, 1), "fragment notified");

    ws.stop(); // close while a fragmented message is pending
    c1.closeFd();

    ws.start();
    Conn c2;
    CHECK(server.acceptAndHandshake(c2), "handshake 2");
    CHECK(waitOpenCount(rec, 2), "open 2");

    c2.sendFrame(true, false, 0x1, "clean");
    CHECK(waitMessageCount(rec, 1), "message delivered on restarted connection");
    auto msgs = rec.messages();
    CHECK(msgs.size() == 1 && msgs[0] == "clean", "no leftover content after restart");

    c2.sendFrame(true, false, 0x8, std::string("\x03\xe8", 2));
    waitClose(rec);
    c2.closeFd();
    ws.stop();
}

// S9: compressed fragmented message, ping in the middle must not disturb decompression
static void s9_compressed_fragmented()
{
    std::cerr << "S9: compressed fragmented message with interleaved ping" << std::endl;
    TestServer server;
    CHECK(server.start(), "server start");
    ix::WebSocket ws;
    ws.enablePerMessageDeflate();
    Recorder rec;
    setupClient(ws, rec, server.port);
    ws.start();

    Conn conn;
    CHECK(server.acceptAndHandshake(conn, true), "handshake with permessage-deflate");
    CHECK(waitOpenCount(rec, 1), "open");

    std::string text = "compress me compress me compress me, split across fragments";
    std::string deflated = deflateRaw(text);
    size_t half = deflated.size() / 2;

    conn.sendFrame(false, true, 0x1, deflated.substr(0, half)); // rsv1 set on first frame
    conn.sendFrame(true, false, 0x9, "x");                      // ping in the middle
    conn.sendFrame(true, false, 0x0, deflated.substr(half));    // final continuation

    CHECK(waitMessageCount(rec, 1), "compressed message delivered");
    auto msgs = rec.messages();
    CHECK(msgs.size() == 1 && msgs[0] == text, "compressed message correctly restored");
    CHECK(rec.count("Ping") == 1, "ping notified");

    bool fin;
    uint8_t opcode;
    std::string payload;
    CHECK(conn.readFrame(fin, opcode, payload), "read client pong");
    CHECK(opcode == 0xA && payload == "x", "auto pong reply");

    conn.sendFrame(true, false, 0x8, std::string("\x03\xe8", 2));
    waitClose(rec);
    conn.closeFd();
    ws.stop();
}

// S10: frame header and payload arriving in separate reads give the same result
static void s10_split_delivery()
{
    std::cerr << "S10: frames arriving in small pieces" << std::endl;
    TestServer server;
    CHECK(server.start(), "server start");
    ix::WebSocket ws;
    Recorder rec;
    setupClient(ws, rec, server.port);
    ws.start();

    Conn conn;
    CHECK(server.acceptAndHandshake(conn), "handshake");
    CHECK(waitOpenCount(rec, 1), "open");

    // Build a fragmented message: TEXT non-fin "AB" + CONT fin "CD",
    // then feed the bytes one at a time.
    std::string wire;
    wire += std::string("\x01\x02", 2);
    wire += "AB";
    wire += std::string("\x80\x02", 2);
    wire += "CD";
    for (char c : wire)
    {
        conn.sendRaw(std::string(1, c));
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }

    CHECK(waitMessageCount(rec, 1), "message delivered");
    auto msgs = rec.messages();
    CHECK(msgs.size() == 1 && msgs[0] == "ABCD", "content assembled");
    CHECK(rec.count("Fragment") == 1, "fragment notified");

    conn.sendFrame(true, false, 0x8, std::string("\x03\xe8", 2));
    waitClose(rec);
    conn.closeFd();
    ws.stop();
}

int main()
{
    s1_fragmented_with_ping();
    s2_unexpected_continuation();
    s3_data_frame_while_pending();
    s4_reconnect_resets_state();
    s5_empty_non_final_frame();
    s6_utf8_split();
    s7_binary_zero_bytes();
    s8_stop_start_resets_state();
    s9_compressed_fragmented();
    s10_split_delivery();

    if (g_failures == 0)
    {
        std::cerr << "ALL SCENARIOS PASSED" << std::endl;
        return 0;
    }
    std::cerr << g_failures << " FAILURES" << std::endl;
    return 1;
}

