    {
        // Process incoming messages and execute callbacks
        // until the connection is closed
        webSocket->run();
    }
    else
    {
        std::stringstream ss;
        ss << "WebSocketServer::handleConnection() HTTP status: " << status.http_status
           << " error: " << status.errorStr;
