struct Event
{
    std::string type;
    std::string payload;
    bool binary = false;
    uint16_t code = 0;
    std::string reason;
};

struct Recorder
{
    std::mutex mutex;
    std::condition_variable cv;
    std::vector<Event> events;

    void add(const Event& e)
    {
        {
            std::lock_guard<std::mutex> lock(mutex);
            events.push_back(e);
        }
        cv.notify_all();
    }

    template<typename Pred>
    bool waitFor(Pred pred, int timeoutMs)
    {
        std::unique_lock<std::mutex> lock(mutex);
        return cv.wait_for(lock, std::chrono::milliseconds(timeoutMs), [&] { return pred(events); });
    }

    size_t count(const std::string& type)
    {
        std::lock_guard<std::mutex> lock(mutex);
        size_t n = 0;
        for (auto& e : events)
            if (e.type == type) n++;
        return n;
    }

    std::vector<std::string> messages()
    {
        std::lock_guard<std::mutex> lock(mutex);
        std::vector<std::string> out;
        for (auto& e : events)
            if (e.type == "Message") out.push_back(e.payload);
        return out;
    }
};

// Raw client connection that masks its frames (as real clients do).
struct RawClient
{
    int fd = -1;

    bool connectTo(uint16_t port)
    {
        fd = socket(AF_INET, SOCK_STREAM, 0);
        sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        addr.sin_port = htons(port);
        if (connect(fd, (sockaddr*) &addr, sizeof(addr)) < 0) return false;

        std::string req = "GET / HTTP/1.1\r\n"
                          "Host: 127.0.0.1\r\n"
                          "Upgrade: websocket\r\n"
                          "Connection: Upgrade\r\n"
                          "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n"
                          "Sec-WebSocket-Version: 13\r\n"
                          "\r\n";
