        std::string resp;
        char buf[1024];
        while (resp.find("\r\n\r\n") == std::string::npos)
        {
            ssize_t n = recv(fd, buf, sizeof(buf), 0);
            if (n <= 0) return false;
            resp.append(buf, (size_t) n);
        }
        return resp.find("101") != std::string::npos;
    }

    bool sendRaw(const std::string& data)
    {
        size_t off = 0;
        while (off < data.size())
        {
            ssize_t n = ::send(fd, data.data() + off, data.size() - off, 0);
            if (n <= 0) return false;
            off += (size_t) n;
        }
        return true;
    }

    bool sendFrame(bool fin, uint8_t opcode, const std::string& payload)
    {
        const uint8_t maskingKey[4] = {0x12, 0x34, 0x56, 0x78};
        std::string frame;
        uint8_t b0 = (uint8_t)((fin ? 0x80 : 0) | (opcode & 0x0f));
        frame.push_back((char) b0);
        size_t len = payload.size();
        if (len < 126)
        {
            frame.push_back((char)(0x80 | len));
        }
        else if (len <= 0xffff)
        {
            frame.push_back((char)(0x80 | 126));
            frame.push_back((char)((len >> 8) & 0xff));
            frame.push_back((char)(len & 0xff));
        }
        else
        {
            frame.push_back((char)(0x80 | 127));
            for (int i = 7; i >= 0; --i) frame.push_back((char)((len >> (8 * i)) & 0xff));
        }
        frame.append((const char*) maskingKey, 4);
        for (size_t i = 0; i < len; ++i) frame.push_back((char)(payload[i] ^ maskingKey[i & 3]));
        return sendRaw(frame);
    }

    bool readN(char* buf, size_t n, int timeoutMs)
    {
        size_t off = 0;
        while (off < n)
        {
            struct pollfd pfd
            {
                fd, POLLIN, 0
            };
            int r = poll(&pfd, 1, timeoutMs);
            if (r <= 0) return false;
            ssize_t got = recv(fd, buf + off, n - off, 0);
            if (got <= 0) return false;
            off += (size_t) got;
        }
        return true;
    }

    bool readFrame(bool& fin, uint8_t& opcode, std::string& payload, int timeoutMs = 5000)
    {
        char hdr[2];
        if (!readN(hdr, 2, timeoutMs)) return false;
        fin = (hdr[0] & 0x80) != 0;
        opcode = (uint8_t)(hdr[0] & 0x0f);
        uint64_t len = (uint8_t) hdr[1] & 0x7f;
        if (len == 126)
        {
            char e[2];
            if (!readN(e, 2, timeoutMs)) return false;
            len = ((uint64_t)(uint8_t) e[0] << 8) | (uint8_t) e[1];
        }
        else if (len == 127)
        {
            char e[8];
            if (!readN(e, 8, timeoutMs)) return false;
            len = 0;
            for (int i = 0; i < 8; ++i) len = (len << 8) | (uint8_t) e[i];
        }
        payload.assign((size_t) len, '\0');
        if (len > 0 && !readN(&payload[0], (size_t) len, timeoutMs)) return false;
        return true;
    }

    void closeFd()
    {
        if (fd >= 0)
        {
            ::close(fd);
            fd = -1;
        }
    }
};

static bool readServerClose(RawClient& client, uint16_t& code, std::string& reason)
{
