        [&rec](std::shared_ptr<ix::ConnectionState> /*state*/,
               ix::WebSocket& /*ws*/,
               const ix::WebSocketMessagePtr& msg) {
            Event e;
            switch (msg->type)
            {
                case ix::WebSocketMessageType::Message:
                    e.type = "Message";
                    e.payload = msg->str;
                    e.binary = msg->binary;
                    break;
                case ix::WebSocketMessageType::Fragment: e.type = "Fragment"; break;
                case ix::WebSocketMessageType::Ping:
                    e.type = "Ping";
                    e.payload = msg->str;
                    break;
                case ix::WebSocketMessageType::Pong:
                    e.type = "Pong";
                    e.payload = msg->str;
                    break;
                case ix::WebSocketMessageType::Open: e.type = "Open"; break;
                case ix::WebSocketMessageType::Close:
                    e.type = "Close";
                    e.code = msg->closeInfo.code;
                    e.reason = msg->closeInfo.reason;
                    break;
                case ix::WebSocketMessageType::Error:
                    e.type = "Error";
                    e.payload = msg->errorInfo.reason;
                    break;
            }
            rec.add(e);
        });
    if (!server.listenAndStart())
    {
        std::cerr << "FAIL: server listen" << std::endl;
        return 1;
    }

    // T1: valid fragmented message with interleaved ping
    std::cerr << "T1: server receives fragmented message with interleaved ping" << std::endl;
    {
        RawClient c;
        CHECK(c.connectTo((uint16_t) port), "connect+handshake");
        c.sendFrame(false, 0x1, "Hello, ");
        c.sendFrame(true, 0x9, "p");
        c.sendFrame(true, 0x0, "world");

        CHECK(rec.waitFor([](const std::vector<Event>& ev) {
            for (auto& e : ev)
                if (e.type == "Message") return true;
            return false;
        },
                          5000),
              "message delivered");
        auto msgs = rec.messages();
        CHECK(msgs.size() == 1 && msgs[0] == "Hello, world", "assembled content");
        CHECK(rec.count("Fragment") == 1, "fragment notified");
        CHECK(rec.count("Ping") == 1, "ping notified");

        // server should auto-reply with a pong
        bool fin;
        uint8_t opcode;
        std::string payload;
        CHECK(c.readFrame(fin, opcode, payload), "read server pong");
        CHECK(opcode == 0xA && payload == "p", "server auto pong");

        c.sendFrame(true, 0x8, std::string("\x03\xe8", 2));
        c.closeFd();
    }

