        RawClient c;
        CHECK(c.connectTo((uint16_t) port), "connect+handshake");
        c.sendFrame(false, 0x1, "Hello, ");
        c.sendFrame(true, 0x9, "p");
        c.sendFrame(true, 0x0, "world");

        CHECK(rec.waitFor([](const std::vector<Event>& ev) {
            for (auto& e : ev)
                if (e.type == "Message") return true;
            return false;
        },
                          5000),
              "message delivered");
        auto msgs = rec.messages();
        CHECK(msgs.size() == 1 && msgs[0] == "Hello, world", "assembled content");
        CHECK(rec.count("Fragment") == 1, "fragment notified");
        CHECK(rec.count("Ping") == 1, "ping notified");

        // server should auto-reply with a pong
        bool fin;
        uint8_t opcode;
        std::string payload;
        CHECK(c.readFrame(fin, opcode, payload), "read server pong");
        CHECK(opcode == 0xA && payload == "p", "server auto pong");

        c.sendFrame(true, 0x8, std::string("\x03\xe8", 2));
        c.closeFd();
    }

    // T2: continuation without pending message -> server closes with 1002
    std::cerr << "T2: server rejects unexpected continuation" << std::endl;
    {
        size_t closesBefore = rec.count("Close");
        RawClient c;
        CHECK(c.connectTo((uint16_t) port), "connect+handshake");
        c.sendFrame(true, 0x0, "x");

        uint16_t code;
        std::string reason;
        CHECK(readServerClose(c, code, reason), "server close frame");
        CHECK(code == 1002, "close code 1002");
        CHECK(reason.find("continuation") != std::string::npos, "reason mentions continuation");

        CHECK(rec.waitFor([closesBefore](const std::vector<Event>& ev) {
            size_t n = 0;
            for (auto& e : ev)
                if (e.type == "Close") n++;
            return n > closesBefore;
        },
                          5000),
              "close notified");
        CHECK(rec.count("Message") == 1, "no new message delivered");
        c.closeFd();
    }

    // T3: new data frame while fragmented message pending -> 1002 data out of sequence
    std::cerr << "T3: server rejects data frame while message pending" << std::endl;
    {
        size_t fragmentsBefore = rec.count("Fragment");
        RawClient c;
        CHECK(c.connectTo((uint16_t) port), "connect+handshake");
        c.sendFrame(false, 0x1, "AB");
        // wait for the fragment to be seen so ordering is deterministic
        CHECK(rec.waitFor([fragmentsBefore](const std::vector<Event>& ev) {
            size_t n = 0;
            for (auto& e : ev)
                if (e.type == "Fragment") n++;
            return n > fragmentsBefore;
        },
                          5000),
              "fragment notified");
        c.sendFrame(true, 0x1, "CD"); // offending new message frame

        uint16_t code;
        std::string reason;
        CHECK(readServerClose(c, code, reason), "server close frame");
        CHECK(code == 1002, "close code 1002");
        CHECK(reason.find("data message") != std::string::npos, "reason mentions data message");
        CHECK(rec.count("Message") == 1, "no new message delivered");
        c.closeFd();
    }

    // T4: unfinished message abandoned on disconnect; next connection is clean
    std::cerr << "T4: server-side pending message dropped on disconnect" << std::endl;
    {
        RawClient c1;
        CHECK(c1.connectTo((uint16_t) port), "connect+handshake 1");
        c1.sendFrame(false, 0x1, "LEFTOVER");
        std::this_thread::sleep_for(std::chrono::milliseconds(200));
        c1.closeFd(); // abrupt drop mid-message

        RawClient c2;
        CHECK(c2.connectTo((uint16_t) port), "connect+handshake 2");
        c2.sendFrame(true, 0x1, "ok");
        CHECK(rec.waitFor([](const std::vector<Event>& ev) {
            for (auto& e : ev)
                if (e.type == "Message" && e.payload == "ok") return true;
            return false;
        },
                          5000),
              "message on new connection delivered");
        auto msgs = rec.messages();
        CHECK(msgs.size() == 2 && msgs[1] == "ok", "no leftover content");
        c2.sendFrame(true, 0x8, std::string("\x03\xe8", 2));
        c2.closeFd();
    }

    server.stop();

    if (g_failures == 0)
    {
        std::cerr << "ALL SERVER SCENARIOS PASSED" << std::endl;
        return 0;
    }
    std::cerr << g_failures << " FAILURES" << std::endl;
    return 1;
}

